TX=$(curl -s http://127.0.0.1:18090/json_rpc -d '{
  "jsonrpc":"2.0","id":"0","method":"transfer",
  "params":{"destinations":[{"amount":1000000000000,"address":"<ADDR_B>"}],
            "account_index":0,"priority":1,"ring_size":11,
            "do_not_relay":true,"get_tx_key":true,"get_tx_metadata":true}}')
TX_META=$(echo "$TX" | python3 -c 'import sys,json; print(json.load(sys.stdin)["result"]["tx_metadata"])')
